SELECT CASE WHEN o.amount >= 1230 THEN 'high' WHEN o.amount >= 450 THEN 'mid' ELSE 'low' END AS amount_bucket, MAX(oi.quantity) AS max_quantity, AVG(oi.unit_price) AS avg_unit_price FROM order_items oi LEFT JOIN orders o ON o.id = oi.order_id WHERE oi.quantity BETWEEN 4 AND 7 GROUP BY CASE WHEN o.amount >= 1230 THEN 'high' WHEN o.amount >= 450 THEN 'mid' ELSE 'low' END HAVING AVG(oi.unit_price) >= 250 ORDER BY avg_unit_price DESC
